// Mapa de arquitetura: cada servico fica na zona do seu papel (docs/arquitetura/agentes.md), as
// zonas seguem o caminho da requisicao, e o desenho mostra o que e essencial e o que degrada.
const dark = !(context.grafana && context.grafana.theme && context.grafana.theme.isLight);
const C = dark
  ? { text: '#d8d9da', muted: '#8e9bae', box: '#1b1f27', bg: '#111217', line: '#556070', edge: '#6b7788', zone: 'rgba(255,255,255,0.035)', zoneLine: '#2b3340', accent: '#5794f2' }
  : { text: '#24292e', muted: '#6b7785', box: '#ffffff', bg: '#f7f8fa', line: '#b8c2cc', edge: '#8a97a6', zone: 'rgba(0,0,0,0.035)', zoneLine: '#dde3ea', accent: '#1f60c4' };
const GREEN = '#73bf69', ORANGE = '#ff9830', RED = '#f2495c', GRAY = '#8e8e8e';
const health = (f) => (f == null || isNaN(f) ? GRAY : f >= 0.05 ? RED : f > 0.0001 ? ORANGE : GREEN);

const A = {}, B = {}, L = {}, K = {};
for (const s of context.panel.data.series) {
  const v = s.fields.find((f) => f.type === 'number');
  if (!v || !v.labels || !v.labels.client || !v.labels.server) continue;
  const val = v.values[v.values.length - 1];
  if (val == null || isNaN(val)) continue;
  const key = v.labels.client + '>' + v.labels.server, kind = v.labels.client_assistant_call_kind || '';
  if (s.refId === 'C') L[key] = val;
  else if (s.refId === 'B') B[key] = (B[key] || 0) + val;
  else {
    A[key] = (A[key] || 0) + val;
    K[key] = K[key] || {};
    K[key][kind] = (K[key][kind] || 0) + val;
  }
}
const edges = Object.keys(A)
  .filter((k) => A[k] > 0 && k.split('>')[0] !== k.split('>')[1])
  .map((k) => {
    const [s, t] = k.split('>');
    return { k, s, t, v: A[k], f: Math.min(1, (B[k] || 0) / A[k]), lat: L[k], kinds: K[k] || {} };
  });
const names = [...new Set(edges.flatMap((e) => [e.s, e.t]))];

// --- Zonas ---------------------------------------------------------------------------------
const LLM = /openai|anthropic|groq|deepseek|together|openrouter|huggingface|mistral|cohere|perplexity|generativelanguage|api\.x\.ai|localai|ollama/i;
const ZONES = [
  { title: 'CLIENTE', sub: 'interface Flutter', col: 0, match: (n) => n === 'user' },
  { title: 'BORDA', sub: 'única porta pública', col: 1, match: (n) => n === 'assistant-api' },
  { title: 'ORQUESTRAÇÃO', sub: 'grafo do chat', col: 2, match: (n) => n === 'agent-orchestrator' },
  { title: 'FERRAMENTAS', sub: 'catálogo e governança', col: 3, match: (n) => n === 'tool-service' },
  { title: 'MCP', sub: 'servidores externos', col: 3, match: (n) => n === 'mcp-service' },
  { title: 'DADOS', sub: 'estado e índice', col: 4, match: (n) => ['mysql', 'redis', 'qdrant'].includes(n) },
  { title: 'PROVEDORES DE IA', sub: 'intercambiáveis', col: 5, match: (n) => LLM.test(n) },
  { title: 'SERVIÇOS EXTERNOS', sub: 'Google e outros', col: 5, match: (n) => n.includes('.') },
  { title: 'OUTROS SERVIÇOS', sub: '', col: 3, match: () => true },
];
const NOTE = {
  user: 'Quem chama a API de fora: a interface ou o portal.',
  'assistant-api': 'Única porta pública: autenticação, rotas, WebSocket. Sem ela nada atende.',
  'agent-orchestrator': 'Grafo do chat (LangGraph). Em modo local roda dentro da API; separado, o chat depende dele.',
  'tool-service': 'Catálogo e execução das ferramentas. Fora do ar, o agente responde sem ferramenta.',
  'mcp-service': 'Servidores MCP. Fora do ar, o assistente responde sem essas capacidades.',
  mysql: 'Banco relacional: usuários, aulas, transcrições, consumo. A API e o orquestrador dependem dele.',
  redis: 'Limite de taxa e cache de status dos provedores. Opcional: a conversa segue sem ele.',
  qdrant: 'Índice vetorial das aulas e memórias. Fora do ar, a resposta vem do conhecimento geral.',
};
const NOTE_LLM = 'Provedor de IA. Chat pelo grafo vem do orquestrador; a API chama direto no streaming e para consultar status e saldo. Se o usuário não escolheu um, o que falha cai para o próximo; se escolheu, a falha é mostrada.';
const ESSENTIAL = new Set(['assistant-api', 'agent-orchestrator', 'mysql']);
const noteOf = (n) => NOTE[n] || (LLM.test(n) ? NOTE_LLM : n.includes('.') ? 'API externa chamada pelo sistema.' : '');

const zoneOf = (n) => ZONES.find((z) => z.match(n));
const zones = ZONES.filter((z) => names.some((n) => zoneOf(n) === z));
zones.forEach((z) => {
  z.members = names.filter((n) => zoneOf(n) === z);
  const order = ['mysql', 'redis', 'qdrant'];
  z.members.sort((a, b) => (order.indexOf(a) < 0 ? 9 : order.indexOf(a)) - (order.indexOf(b) < 0 ? 9 : order.indexOf(b)) || a.localeCompare(b));
});
const colIds = [...new Set(zones.map((z) => z.col))].sort((a, b) => a - b);
const colsZ = colIds.map((c) => zones.filter((z) => z.col === c));
const nodeCol = {};
colsZ.forEach((zs, k) => zs.forEach((z) => z.members.forEach((n) => (nodeCol[n] = k))));
const GAP = 1.5;
const unitsOf = (zs) => zs.reduce((u, z, i) => u + (i ? GAP : 0) + z.members.length, 0);
const STEP = 1000 / (Math.max(1, ...colsZ.map(unitsOf)) + 1);
const X = {}, Y = {};
const place = () =>
  colsZ.forEach((zs, k) => {
    const total = unitsOf(zs);
    let u = 0;
    zs.forEach((z, i) => {
      if (i) u += GAP;
      z.members.forEach((n) => {
        X[n] = ((k + 0.5) / colsZ.length) * 1000;
        Y[n] = 500 + (u + 0.5 - total / 2) * STEP;
        u += 1;
      });
    });
  });
place();
// Dentro de cada zona, a ordem segue a altura de quem chama (menos cruzamentos).
for (let pass = 0; pass < 3; pass++) {
  colsZ.forEach((zs, k) => {
    if (k === 0) return;
    zs.forEach((z) => {
      const b = {};
      z.members.forEach((n) => {
        const ps = edges.filter((e) => e.t === n && nodeCol[e.s] < k).map((e) => Y[e.s]);
        b[n] = ps.length ? ps.reduce((a, c) => a + c, 0) / ps.length : Y[n];
      });
      z.members.sort((x, y) => b[x] - b[y] || x.localeCompare(y));
    });
  });
  place();
}

// Para que serve a chamada a um provedor (rotulo do collector): so consulta de status (saldo, modelos)?
const statusOnly = (e) => (e.kinds.status || 0) > 0 && Object.keys(e.kinds).every((x) => x === 'status');
const kindText = (e, f) => {
  const ks = Object.keys(e.kinds).filter(Boolean);
  return ks.length ? '<br/>' + ks.map((x) => (x === 'status' ? 'verificação de status' : 'chat') + ': ' + f(e.kinds[x])).join('<br/>') : '';
};
const maxEdge = Math.max(1e-9, ...edges.map((e) => e.v));
const short = (n) => (n.length > 24 ? n.slice(0, 23) + '…' : n);
const fmtInt = (n) => (n >= 10000 ? (n / 1000).toFixed(1) + ' mil' : String(Math.round(n)));
const fmtLat = (s) => (s == null || isNaN(s) ? '' : s < 1 ? Math.round(s * 1000) + ' ms' : s.toFixed(1) + ' s');

// Caminho de uma ligacao em coordenadas de dados. Para frente: curva em S; se pula colunas, passa
// por fora das zonas do meio (acima ou abaixo); se a chamada volta (orquestrador -> API em
// /internal/devices/invoke), arco por cima.
const COLW = 1000 / colsZ.length;
const colX = (k) => (k + 0.5) * COLW;
const colBand = colsZ.map((zs) => {
  const ys = zs.flatMap((z) => z.members.map((n) => Y[n]));
  return [Math.min(...ys) - STEP * 1.5, Math.max(...ys) + STEP];
});
const waypoints = (e) => {
  if (e.wp) return e.wp;
  const ps = [X[e.s], Y[e.s]], pt = [X[e.t], Y[e.t]];
  const pts = [ps, [ps[0] + COLW * 0.3, ps[1]]];
  for (let k = nodeCol[e.s] + 1; k < nodeCol[e.t]; k++) {
    let y = ps[1] + (pt[1] - ps[1]) * ((colX(k) - ps[0]) / (pt[0] - ps[0]));
    const [lo, hi] = colBand[k];
    if (y > lo && y < hi) y = y - lo < hi - y ? lo : hi;
    pts.push([colX(k), y]);
  }
  pts.push([pt[0] - COLW * 0.3, pt[1]], pt);
  return (e.wp = pts);
};
const spline = (pts, t) => {
  const n = pts.length - 1, s = Math.min(n - 1e-9, t * n), i = Math.floor(s), u = s - i;
  const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(n, i + 2)];
  const f = (q0, q1, q2, q3) => 0.5 * (2 * q1 + (-q0 + q2) * u + (2 * q0 - 5 * q1 + 4 * q2 - q3) * u * u + (-q0 + 3 * q1 - 3 * q2 + q3) * u * u * u);
  return [f(p0[0], p1[0], p2[0], p3[0]), f(p0[1], p1[1], p2[1], p3[1])];
};
const pathPoint = (e, t) => {
  const p0 = [X[e.s], Y[e.s]], p3 = [X[e.t], Y[e.t]], u = 1 - t;
  if (nodeCol[e.t] < nodeCol[e.s]) {
    const c = [(p0[0] + p3[0]) / 2, Math.min(p0[1], p3[1]) - STEP * 1.6];
    return [u * u * p0[0] + 2 * u * t * c[0] + t * t * p3[0], u * u * p0[1] + 2 * u * t * c[1] + t * t * p3[1]];
  }
  if (nodeCol[e.t] - nodeCol[e.s] > 1) return spline(waypoints(e), t);
  const mx = (p0[0] + p3[0]) / 2;
  const w = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
  return [w[0] * p0[0] + (w[1] + w[2]) * mx + w[3] * p3[0], (w[0] + w[1]) * p0[1] + (w[2] + w[3]) * p3[1]];
};

// Caixas das zonas, atras de tudo.
const zoneSeries = (NW, NH) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 0,
  z: 0,
  silent: true,
  encode: { x: 0, y: [1, 2] },
  data: zones.map((z, i) => [X[z.members[0]], Math.min(...z.members.map((n) => Y[n])), Math.max(...z.members.map((n) => Y[n])), i]),
  renderItem: (params, api) => {
    const z = zones[api.value(3)];
    const top = api.coord([api.value(0), api.value(1)]), bot = api.coord([api.value(0), api.value(2)]);
    const x = top[0] - NW / 2 - 12, y = top[1] - NH / 2 - 40;
    return {
      type: 'group',
      children: [
        { type: 'rect', shape: { x, y, width: NW + 24, height: bot[1] - top[1] + NH + 52, r: 10 }, style: { fill: C.zone, stroke: C.zoneLine, lineWidth: 1 } },
      ],
    };
  },
});

// Titulos das zonas, acima das linhas e com fundo, para nao serem riscados por elas.
const zoneTitles = (NW, NH) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 0,
  z: 6,
  silent: true,
  encode: { x: 0, y: 1 },
  data: zones.map((z, i) => [X[z.members[0]], Math.min(...z.members.map((n) => Y[n])), i]),
  renderItem: (params, api) => {
    const z = zones[api.value(2)];
    const top = api.coord([api.value(0), api.value(1)]);
    const x = top[0] - NW / 2 - 12, y = top[1] - NH / 2 - 40;
    return {
      type: 'group',
      children: [
        { type: 'rect', shape: { x: x + 6, y: y + 3, width: Math.max(z.title.length * 6.4, (z.sub || '').length * 5.4) + 12, height: z.sub ? 30 : 17, r: 5 }, style: { fill: C.bg, opacity: 0.85 } },
        { type: 'text', style: { text: z.title, x: x + 12, y: y + 12, fill: C.muted, font: '600 10px sans-serif', textVerticalAlign: 'middle' } },
        ...(z.sub ? [{ type: 'text', style: { text: z.sub, x: x + 12, y: y + 26, fill: C.muted, font: '10px sans-serif', textVerticalAlign: 'middle' } }] : []),
      ],
    };
  },
});

// Seta e rotulo de cada ligacao. Continua: o destino e essencial; tracejada: o sistema degrada sem ele.
const edgeSeries = (NW, NH, width, color, label, tip) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 0,
  z: 2,
  encode: { x: [0, 2], y: [1, 3] },
  data: edges.map((e, i) => [X[e.s], Y[e.s], X[e.t], Y[e.t], i]),
  tooltip: { formatter: (p) => tip(edges[p.dataIndex]) },
  renderItem: (params, api) => {
    const e = edges[api.value(4)];
    const c1 = api.coord([api.value(0), api.value(1)]), c2 = api.coord([api.value(2), api.value(3)]);
    const inside = (p, c) => Math.abs(p[0] - c[0]) < NW / 2 + 3 && Math.abs(p[1] - c[1]) < NH / 2 + 3;
    const pts = [];
    for (let i = 0; i <= 60; i++) {
      const p = api.coord(pathPoint(e, i / 60));
      if (!inside(p, c1) && !inside(p, c2)) pts.push(p);
    }
    if (pts.length < 3) return null;
    const last = pts[pts.length - 1], prev = pts[pts.length - 3];
    const ang = Math.atan2(last[1] - prev[1], last[0] - prev[0]), col = color(e), w = width(e);
    const head = [
      last,
      [last[0] - 10 * Math.cos(ang - 0.4), last[1] - 10 * Math.sin(ang - 0.4)],
      [last[0] - 10 * Math.cos(ang + 0.4), last[1] - 10 * Math.sin(ang + 0.4)],
    ];
    const showLabel = edges.length <= 8 || e.v >= maxEdge * 0.05;
    const txt = showLabel ? (statusOnly(e) ? 'status ' : '') + label(e) : '', pw = txt.length * 6.4 + 12;
    const m = pts[Math.floor((pts.length - 1) * (pts.length < 24 ? 0.5 : 0.72))];
    return {
      type: 'group',
      children: [
        { type: 'polyline', shape: { points: pts }, style: { stroke: col, lineWidth: w, opacity: statusOnly(e) ? 0.4 : ESSENTIAL.has(e.t) ? 0.75 : 0.5, fill: 'none', lineDash: statusOnly(e) ? [2, 4] : ESSENTIAL.has(e.t) ? null : [6, 4] } },
        { type: 'polygon', shape: { points: head }, style: { fill: col, opacity: 0.9 } },
        ...(showLabel ? [{ type: 'rect', shape: { x: m[0] - pw / 2, y: m[1] - 9, width: pw, height: 18, r: 9 }, style: { fill: C.bg, stroke: C.line, lineWidth: 1 } }] : []),
        { type: 'text', style: { text: txt, x: m[0], y: m[1], textAlign: 'center', textVerticalAlign: 'middle', fill: C.text, font: '11px sans-serif' } },
      ],
    };
  },
});

// Cartoes dos servicos, acima das setas. Faixa azul: dependencia essencial.
const nodeSeries = (NW, NH, border, line2, extra) => ({
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  zlevel: 1,
  z: 5,
  encode: { x: 0, y: 1 },
  data: names.map((n) => [X[n], Y[n], n]),
  tooltip: { formatter: (p) => '<b>' + p.value[2] + '</b>' + (ESSENTIAL.has(p.value[2]) ? ' · essencial' : '') + '<br/>' + noteOf(p.value[2]) + extra(p.value[2]) },
  renderItem: (params, api) => {
    const n = api.value(2), p = api.coord([api.value(0), api.value(1)]);
    const sub = line2(n), x = p[0] - NW / 2, y = p[1] - NH / 2;
    return {
      type: 'group',
      children: [
        { type: 'rect', shape: { x, y, width: NW, height: NH, r: 8 }, style: { fill: C.box, stroke: border(n), lineWidth: 2 } },
        ...(ESSENTIAL.has(n) ? [{ type: 'rect', shape: { x: x + 1, y: y + 8, width: 3, height: NH - 16, r: 1.5 }, style: { fill: C.accent } }] : []),
        { type: 'text', style: { text: short(n), x: p[0], y: p[1] - (sub ? 8 : 0), textAlign: 'center', textVerticalAlign: 'middle', fill: C.text, font: '600 12px sans-serif' } },
        ...(sub ? [{ type: 'text', style: { text: sub, x: p[0], y: p[1] + 9, textAlign: 'center', textVerticalAlign: 'middle', fill: C.muted, font: '10px sans-serif' } }] : []),
      ],
    };
  },
});

const legend = {
  type: 'group',
  left: 16,
  bottom: 8,
  children: [
    { type: 'line', x: 0, y: 7, shape: { x1: 0, y1: 0, x2: 26, y2: 0 }, style: { stroke: C.edge, lineWidth: 2 } },
    { type: 'text', x: 34, y: 0, style: { text: 'dependência essencial', fill: C.muted, font: '11px sans-serif' } },
    { type: 'line', x: 170, y: 7, shape: { x1: 0, y1: 0, x2: 26, y2: 0 }, style: { stroke: C.edge, lineWidth: 2, lineDash: [6, 4] } },
    { type: 'text', x: 204, y: 0, style: { text: 'opcional: o sistema continua sem ela', fill: C.muted, font: '11px sans-serif' } },
    { type: 'line', x: 560, y: 7, shape: { x1: 0, y1: 0, x2: 26, y2: 0 }, style: { stroke: C.edge, lineWidth: 2, lineDash: [2, 4] } },
    { type: 'text', x: 594, y: 0, style: { text: 'só consulta de status (saldo, modelos)', fill: C.muted, font: '11px sans-serif' } },
    { type: 'rect', x: 420, y: 2, shape: { x: 0, y: 0, width: 3, height: 12, r: 1.5 }, style: { fill: C.accent } },
    { type: 'text', x: 430, y: 0, style: { text: 'serviço essencial', fill: C.muted, font: '11px sans-serif' } },
  ],
};
// Janela exibida: segue o relogio do topo do Grafana. Termina "agora" = ao vivo; senao e um momento passado.
const rangeLabel = () => {
  const tr = context.panel.data.timeRange;
  const ms = (m) => (m && m.valueOf ? Number(m.valueOf()) : NaN);
  const from = tr && ms(tr.from), to = tr && ms(tr.to);
  if (!from || !to) return '';
  const live = Math.abs(Date.now() - to) < 90000;
  const f = (t) => new Date(t).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', second: to - from < 600000 ? '2-digit' : undefined });
  const mins = Math.round((to - from) / 60000);
  const span = mins >= 120 ? Math.round(mins / 60) + ' h' : mins < 1 ? '< 1 min' : mins + ' min';
  return live ? 'AO VIVO · últimos ' + span : 'MOMENTO PASSADO · ' + f(from) + ' → ' + f(to);
};
const rangeText = () => {
  const t = rangeLabel();
  const past = t.startsWith('MOMENTO');
  return t ? [{ type: 'text', right: 16, top: 6, style: { text: t, fill: past ? ORANGE : C.muted, font: '600 11px sans-serif' } }] : [];
};
const base = {
  animation: false,
  grid: { left: 16, right: 16, top: 24, bottom: 36 },
  xAxis: { type: 'value', min: 0, max: 1000, show: false },
  yAxis: { type: 'value', min: 0, max: 1000, inverse: true, show: false },
  tooltip: { trigger: 'item', confine: true },
  graphic: [legend, ...rangeText()],
};
if (!edges.length) {
  base.graphic = [...rangeText(), { type: 'text', left: 'center', top: 'middle', style: { text: 'ainda sem chamadas entre serviços', fill: C.muted, font: '13px sans-serif' } }];
}
// Mapa de servicos: totais do periodo. A: chamadas; B: falhas; C: latencia media (s) por ligacao.
const NW = 176, NH = 40;
const inOf = (n) => edges.filter((e) => e.t === n);
const inCount = (n) => inOf(n).reduce((a, e) => a + e.v, 0);
const inFail = (n) => inOf(n).reduce((a, e) => a + e.v * e.f, 0);
const lat = (n) => {
  const es = inOf(n).filter((e) => e.lat != null && !isNaN(e.lat));
  const w = es.reduce((a, e) => a + e.v, 0);
  return w ? es.reduce((a, e) => a + e.lat * e.v, 0) / w : null;
};
const maxV = Math.max(1, ...edges.map((e) => e.v));
const nodeFail = (n) => (inCount(n) ? inFail(n) / inCount(n) : null);
const line2 = (n) => {
  const c = inCount(n) || edges.filter((e) => e.s === n).reduce((a, e) => a + e.v, 0);
  if (!c) return '';
  const f = nodeFail(n);
  return [fmtInt(c) + ' chamadas', fmtLat(lat(n)), f ? (f * 100).toFixed(1) + '% falha' : ''].filter(Boolean).join(' · ');
};
return {
  ...base,
  series: [
    zoneSeries(NW, NH),
    zoneTitles(NW, NH),
    edgeSeries(
      NW, NH,
      (e) => 1 + 5 * Math.sqrt(e.v / maxV),
      (e) => (e.f >= 0.05 ? RED : e.f > 0.0001 ? ORANGE : C.edge),
      (e) => fmtInt(e.v),
      (e) => e.s + ' → ' + e.t + '<br/>' + Math.round(e.v) + ' chamadas<br/>falhas: ' + (e.f * 100).toFixed(1) + '%' +
        kindText(e, (n) => Math.round(n) + ' chamadas') + (e.lat != null ? '<br/>latência média: ' + fmtLat(e.lat) : '')),
    nodeSeries(NW, NH, (n) => (inCount(n) ? health(nodeFail(n)) : C.line), line2, (n) => (line2(n) ? '<br/><br/>' + line2(n) : '')),
  ],
};

// Mapa de arquitetura: cada servico fica na zona do seu papel (docs/arquitetura/agentes.md), as
// zonas seguem o caminho da requisicao, e o desenho mostra o que e essencial e o que degrada.
const dark = !(context.grafana && context.grafana.theme && context.grafana.theme.isLight);
const C = dark
  ? { text: '#d8d9da', muted: '#8e9bae', box: '#1b1f27', bg: '#111217', line: '#556070', edge: '#6b7788', zone: 'rgba(255,255,255,0.035)', zoneLine: '#2b3340', accent: '#5794f2' }
  : { text: '#24292e', muted: '#6b7785', box: '#ffffff', bg: '#f7f8fa', line: '#b8c2cc', edge: '#8a97a6', zone: 'rgba(0,0,0,0.035)', zoneLine: '#dde3ea', accent: '#1f60c4' };
const GREEN = '#73bf69', ORANGE = '#ff9830', RED = '#f2495c', GRAY = '#8e8e8e';
const health = (f) => (f == null || isNaN(f) ? GRAY : f >= 0.05 ? RED : f > 0.0001 ? ORANGE : GREEN);

const A = {}, B = {}, L = {}, K = {};
for (const s of context.panel.data.series) {
  const v = s.fields.find((f) => f.type === 'number');
  if (!v || !v.labels || !v.labels.client || !v.labels.server) continue;
  const val = v.values[v.values.length - 1];
  if (val == null || isNaN(val)) continue;
  const key = v.labels.client + '>' + v.labels.server, kind = v.labels.client_assistant_call_kind || '';
  if (s.refId === 'C') L[key] = val;
  else if (s.refId === 'B') B[key] = (B[key] || 0) + val;
  else {
    A[key] = (A[key] || 0) + val;
    K[key] = K[key] || {};
    K[key][kind] = (K[key][kind] || 0) + val;
  }
}
const edges = Object.keys(A)
  .filter((k) => A[k] > 0 && k.split('>')[0] !== k.split('>')[1])
  .map((k) => {
    const [s, t] = k.split('>');
    return { k, s, t, v: A[k], f: Math.min(1, (B[k] || 0) / A[k]), lat: L[k], kinds: K[k] || {} };
  });
const names = [...new Set(edges.flatMap((e) => [e.s, e.t]))];

// --- Zonas ---------------------------------------------------------------------------------
const LLM = /openai|anthropic|groq|deepseek|together|openrouter|huggingface|mistral|cohere|perplexity|generativelanguage|api\.x\.ai|localai|ollama/i;
const ZONES = [
  { title: 'CLIENTE', sub: 'interface Flutter', col: 0, match: (n) => n === 'user' },
  { title: 'BORDA', sub: 'única porta pública', col: 1, match: (n) => n === 'assistant-api' },
  { title: 'ORQUESTRAÇÃO', sub: 'grafo do chat', col: 2, match: (n) => n === 'agent-orchestrator' },
  { title: 'FERRAMENTAS', sub: 'catálogo e governança', col: 3, match: (n) => n === 'tool-service' },
  { title: 'MCP', sub: 'servidores externos', col: 3, match: (n) => n === 'mcp-service' },
  { title: 'DADOS', sub: 'estado e índice', col: 4, match: (n) => ['mysql', 'redis', 'qdrant'].includes(n) },
  { title: 'PROVEDORES DE IA', sub: 'intercambiáveis', col: 5, match: (n) => LLM.test(n) },
  { title: 'SERVIÇOS EXTERNOS', sub: 'Google e outros', col: 5, match: (n) => n.includes('.') },
  { title: 'OUTROS SERVIÇOS', sub: '', col: 3, match: () => true },
];
const NOTE = {
  user: 'Quem chama a API de fora: a interface ou o portal.',
  'assistant-api': 'Única porta pública: autenticação, rotas, WebSocket. Sem ela nada atende.',
  'agent-orchestrator': 'Grafo do chat (LangGraph). Em modo local roda dentro da API; separado, o chat depende dele.',
  'tool-service': 'Catálogo e execução das ferramentas. Fora do ar, o agente responde sem ferramenta.',
  'mcp-service': 'Servidores MCP. Fora do ar, o assistente responde sem essas capacidades.',
  mysql: 'Banco relacional: usuários, aulas, transcrições, consumo. A API e o orquestrador dependem dele.',
  redis: 'Limite de taxa e cache de status dos provedores. Opcional: a conversa segue sem ele.',
  qdrant: 'Índice vetorial das aulas e memórias. Fora do ar, a resposta vem do conhecimento geral.',
};
const NOTE_LLM = 'Provedor de IA. Chat pelo grafo vem do orquestrador; a API chama direto no streaming e para consultar status e saldo. Se o usuário não escolheu um, o que falha cai para o próximo; se escolheu, a falha é mostrada.';
const ESSENTIAL = new Set(['assistant-api', 'agent-orchestrator', 'mysql']);
const noteOf = (n) => NOTE[n] || (LLM.test(n) ? NOTE_LLM : n.includes('.') ? 'API externa chamada pelo sistema.' : '');

const zoneOf = (n) => ZONES.find((z) => z.match(n));
const zones = ZONES.filter((z) => names.some((n) => zoneOf(n) === z));
zones.forEach((z) => {
  z.members = names.filter((n) => zoneOf(n) === z);
  const order = ['mysql', 'redis', 'qdrant'];
  z.members.sort((a, b) => (order.indexOf(a) < 0 ? 9 : order.indexOf(a)) - (order.indexOf(b) < 0 ? 9 : order.indexOf(b)) || a.localeCompare(b));
});
const colIds = [...new Set(zones.map((z) => z.col))].sort((a, b) => a - b);
const colsZ = colIds.map((c) => zones.filter((z) => z.col === c));
const nodeCol = {};
colsZ.forEach((zs, k) => zs.forEach((z) => z.members.forEach((n) => (nodeCol[n] = k))));
const GAP = 1.5;
const unitsOf = (zs) => zs.reduce((u, z, i) => u + (i ? GAP : 0) + z.members.length, 0);
const STEP = 1000 / (Math.max(1, ...colsZ.map(unitsOf)) + 1);
const X = {}, Y = {};
const place = () =>
  colsZ.forEach((zs, k) => {
    const total = unitsOf(zs);
    let u = 0;
    zs.forEach((z, i) => {
      if (i) u += GAP;
      z.members.forEach((n) => {
        X[n] = ((k + 0.5) / colsZ.length) * 1000;
        Y[n] = 500 + (u + 0.5 - total / 2) * STEP;
        u += 1;
      });
    });
  });
place();
// Dentro de cada zona, a ordem segue a altura de quem chama (menos cruzamentos).
for (let pass = 0; pass < 3; pass++) {
  colsZ.forEach((zs, k) => {
    if (k === 0) return;
    zs.forEach((z) => {
      const b = {};
      z.members.forEach((n) => {
        const ps = edges.filter((e) => e.t === n && nodeCol[e.s] < k).map((e) => Y[e.s]);
        b[n] = ps.length ? ps.reduce((a, c) => a + c, 0) / ps.length : Y[n];
      });
      z.members.sort((x, y) => b[x] - b[y] || x.localeCompare(y));
    });
  });
  place();
}

// Para que serve a chamada a um provedor (rotulo do collector): so consulta de status (saldo, modelos)?
const statusOnly = (e) => (e.kinds.status || 0) > 0 && Object.keys(e.kinds).every((x) => x === 'status');
const kindText = (e, f) => {
  const ks = Object.keys(e.kinds).filter(Boolean);
  return ks.length ? '<br/>' + ks.map((x) => (x === 'status' ? 'verificação de status' : 'chat') + ': ' + f(e.kinds[x])).join('<br/>') : '';
};
const maxEdge = Math.max(1e-9, ...edges.map((e) => e.v));
const short = (n) => (n.length > 24 ? n.slice(0, 23) + '…' : n);
const fmtInt = (n) => (n >= 10000 ? (n / 1000).toFixed(1) + ' mil' : String(Math.round(n)));
const fmtLat = (s) => (s == null || isNaN(s) ? '' : s < 1 ? Math.round(s * 1000) + ' ms' : s.toFixed(1) + ' s');

// Caminho de uma ligacao em coordenadas de dados. Para frente: curva em S; se pula colunas, passa
// por fora das zonas do meio (acima ou abaixo); se a chamada volta (orquestrador -> API em
// /internal/devices/invoke), arco por cima.
const COLW = 1000 / colsZ.length;
const colX = (k) => (k + 0.5) * COLW;
const colBand = colsZ.map((zs) => {
  const ys = zs.flatMap((z) => z.members.map((n) => Y[n]));
  return [Math.min(...ys) - STEP * 1.5, Math.max(...ys) + STEP];
});
const waypoints = (e) => {
  if (e.wp) return e.wp;
  const ps = [X[e.s], Y[e.s]], pt = [X[e.t], Y[e.t]];
  const pts = [ps, [ps[0] + COLW * 0.3, ps[1]]];
  for (let k = nodeCol[e.s] + 1; k < nodeCol[e.t]; k++) {
    let y = ps[1] + (pt[1] - ps[1]) * ((colX(k) - ps[0]) / (pt[0] - ps[0]));
    const [lo, hi] = colBand[k];
    if (y > lo && y < hi) y = y - lo < hi - y ? lo : hi;
    pts.push([colX(k), y]);
  }
  pts.push([pt[0] - COLW * 0.3, pt[1]], pt);
  return (e.wp = pts);
};
const spline = (pts, t) => {
  const n = pts.length - 1, s = Math.min(n - 1e-9, t * n), i = Math.floor(s), u = s - i;
  const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(n, i + 2)];
  const f = (q0, q1, q2, q3) => 0.5 * (2 * q1 + (-q0 + q2) * u + (2 * q0 - 5 * q1 + 4 * q2 - q3) * u * u + (-q0 + 3 * q1 - 3 * q2 + q3) * u * u * u);
  return [f(p0[0], p1[0], p2[0], p3[0]), f(p0[1], p1[1], p2[1], p3[1])];
};
const pathPoint = (e, t) => {
  const p0 = [X[e.s], Y[e.s]], p3 = [X[e.t], Y[e.t]], u = 1 - t;
  if (nodeCol[e.t] < nodeCol[e.s]) {
    const c = [(p0[0] + p3[0]) / 2, Math.min(p0[1], p3[1]) - STEP * 1.6];
    return [u * u * p0[0] + 2 * u * t * c[0] + t * t * p3[0], u * u * p0[1] + 2 * u * t * c[1] + t * t * p3[1]];
  }
  if (nodeCol[e.t] - nodeCol[e.s] > 1) return spline(waypoints(e), t);
  const mx = (p0[0] + p3[0]) / 2;
  const w = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
  return [w[0] * p0[0] + (w[1] + w[2]) * mx + w[3] * p3[0], (w[0] + w[1]) * p0[1] + (w[2] + w[3]) * p3[1]];
};

// Caixas das zonas, atras de tudo.
